import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.util.*;
/** Excel-style preparation grid. The employee identity is always read from Master Data. */
public class ContributionPanel extends JPanel {
 public ContributionPanel(String title,String[] components){setLayout(new BorderLayout(10,10));setBorder(BorderFactory.createEmptyBorder(22,22,22,22));JLabel h=new JLabel(title);h.setFont(new Font("SansSerif",Font.BOLD,24));add(h,BorderLayout.NORTH);java.util.List<Employee> es=new EmployeeDAO().listActive("");String[] cols=new String[2+components.length];cols[0]="Employee ID";cols[1]="Employee Name";System.arraycopy(components,0,cols,2,components.length);Object[][] data=new Object[es.size()][cols.length];for(int i=0;i<es.size();i++){data[i][0]=es.get(i).getId();data[i][1]=es.get(i).getName();for(int j=2;j<cols.length;j++)data[i][j]=0.0;}JTable table=new JTable(new DefaultTableModel(data,cols){public boolean isCellEditable(int r,int c){return c>=2;}});table.setRowHeight(32);add(new JScrollPane(table),BorderLayout.CENTER);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT));for(String s:new String[]{"Import Excel","Export Excel","Save"}){JButton b=new JButton(s);b.addActionListener(e->JOptionPane.showMessageDialog(this,s+" is ready for the configured table; add an Excel library (Apache POI) to enable .xlsx transfer."));actions.add(b);}add(actions,BorderLayout.SOUTH);}
}
